import {createAccountServices} from '../../services/account.services';
import {createGeneralSettingServices} from '../../services/general-setting.services';
import {createNotificationService} from '../../services/notification.services';
import {useFetchRequest} from '../useFetch';

export const useCreateNotiServices = () => {
  const fetchRequest = useFetchRequest();
  return createNotificationService(fetchRequest);
};

export const useGeneralSettingServices = () => {
  const fetchRequest = useFetchRequest();
  return createGeneralSettingServices(fetchRequest);
};

export const useAccountServices = () => {
  const fetchRequest = useFetchRequest();
  return createAccountServices(fetchRequest);
};
