import {isEmpty} from 'lodash';
import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {Image, TouchableOpacity, View} from 'react-native';
import styles from './styles';
import TextCM from '../../../../../../../components/Text';
import {IconNoImage} from '../../../../../../../assets/images';
import {String} from '../../../../../../../constants';
import CheckboxCM from '../../../../../../../components/Checkbox';
import ButtonCM from '../../../../../../../components/Button';
import Toast from 'react-native-toast-message';
import ImageCropPicker from '../../../../../../../components/ImageCropPicker';
import {useAccountServices} from '../../../../../../../hook/apiHook/useApi';

type Props = {
  onSave: (value: string) => void;
};

const SignatureFromImage = ({onSave}: Props) => {
  const {t} = useTranslation();
  const [image, setImage] = useState<any>();
  const [imageRemoveBg, setImageRemoveBg] = useState(null);
  const AccountServices = useAccountServices();
  const onContinue = () => {
    if (imageRemoveBg) {
      onSave(imageRemoveBg);
    } else {
      onSave(image?.data);
    }
  };

  const onChoiceImage = () => {
    ImageCropPicker.ChoosePhoto({
      includeBase64Enabled: true,
    }).then((res: any) => {
      if (res) {
        if (res.size > 2000000) {
          Toast.show({
            type: 'error',
            text1: t('AC.TxtAlertMaxImageSize'),
          });
        } else {
          setImage(res);
          setImageRemoveBg(null);
        }
      }
    });
  };

  const handleClearBackgroundImage = async () => {
    try {
      if (!isEmpty(imageRemoveBg)) {
        setImageRemoveBg(null);
        return;
      }
      const imageClearBgData = await AccountServices.clearBackground(
        (image as any)?.data,
      );
      setImageRemoveBg(imageClearBgData.data);
    } catch (error) {
      console.log(error);
      Toast.show({
        type: 'error',
        text1: t('AC.alert.clearBackgroundErr'),
      });
    }
  };

  return (
    <View style={styles.container}>
      <View style={styles.body}>
        <View style={styles.viewFormPicImage}>
          <View style={styles.viewImageHeader}>
            <View style={styles.viewTxtSignatureImage}>
              <TextCM style={styles.txtSignatureImag}>
                {t('AC.TxtSignatureImage')}
                <TextCM style={styles.txtRed}> * </TextCM>
              </TextCM>
              <TextCM style={styles.txtNote}>{t('AC.TxtMaxImageSize')}</TextCM>
            </View>
            <TextCM style={styles.txtNote}>
              {t('AC.TxtSupportedFormats')}
            </TextCM>
          </View>
          {!isEmpty(image) ? (
            <View style={styles.viewImage}>
              <Image
                style={styles.styleImage}
                source={{
                  uri:
                    String.PREFIX_IMG_BASE64 + (imageRemoveBg || image?.data),
                }}
              />
            </View>
          ) : (
            <View style={styles.viewNoImage}>
              <IconNoImage width={60} height={60} />
            </View>
          )}
          <View style={styles.viewAction}>
            {!isEmpty(image) ? (
              <CheckboxCM
                label={t('AC.clearBg')}
                checked={!!imageRemoveBg}
                onChange={() => {
                  handleClearBackgroundImage();
                }}
                labelStyle={styles.txtRemoveBg}
              />
            ) : (
              <View />
            )}
            <TouchableOpacity
              style={styles.btnUploadImage}
              onPress={onChoiceImage}>
              <TextCM style={styles.txtUpload}>
                {isEmpty(image) ? t('AC.uploadImage') : t('AC.TxtReload')}
              </TextCM>
            </TouchableOpacity>
          </View>
        </View>
      </View>
      <View style={styles.footer}>
        <ButtonCM
          label={t('CM.BtnContinue')}
          onPress={onContinue}
          disabled={isEmpty(image) && isEmpty(imageRemoveBg)}
        />
      </View>
    </View>
  );
};

export default SignatureFromImage;
